// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 value1, uint256 value2) public {
        uint256 max = type(uint256).max / 2;
        value1 = bound(value1, 0, max);
        value2 = bound(value2, 0, max);

        address actor = address(0x1234);
        vm.deal(actor, value1 + value2);

        vm.prank(actor);
        c.addToBalance{value: value1}();

        bool ok;
        vm.prank(actor);
        try c.addToBalance{value: value2}() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
